with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التنبؤات الموسمية والخدمات المناخية الاحتمالية','مصادر القابلية للتنبؤ والأنماط المحيطية والجوية واسعة النطاق وإنتاج المجموعات الموسمية ومعايرتها والتحقق منها وتحويلها إلى خدمات مناخية.',65,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'مصادر القابلية للتنبؤ والأنماط المناخية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إنتاج التوقع الموسمي والتحقق والخدمات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('seasonal-prediction-system','منظومة التنبؤات الجوية الموسمية','مصادر المهارة ومكونات النظام','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع التنبؤات الموسمية بين النماذج المقترنة والمشاهدات والحالة المحيطية والأنماط المناخية واسعة النطاق. وهي احتمالية بطبيعتها، وتصف تغير فرص الفئات المناخية خلال أشهر لا حالة الطقس اليومية."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"منظومة التنبؤات الجوية الموسمية","text":"صمم مخططاً يوضح مدخلات ومخرجات منظومة تنبؤ موسمي. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مخططاً يوضح مدخلات ومخرجات منظومة تنبؤ موسمي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9160,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('seasonal-predictability-sources','مصادر قابلية التنبؤ الموسمي','المحيطات والسطوح والأنماط البطيئة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تأتي قابلية التنبؤ الموسمي من مكونات بطيئة التغير نسبياً مثل حرارة سطح البحر ورطوبة التربة والغطاء الثلجي، إضافة إلى التفاعلات الجوية الداخلية. تختلف المهارة باختلاف المنطقة والموسم والمتغير."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مصادر قابلية التنبؤ الموسمي","text":"قارن مصادر القابلية للتنبؤ في منطقة ساحلية وأخرى داخلية. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مصادر القابلية للتنبؤ في منطقة ساحلية وأخرى داخلية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9170,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('enso-seasonal-teleconnection','إل نينيو والتذبذب الجنوبي والاتصالات المناخية','تأثيرات المحيط الهادئ بعيدة المدى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يغير ENSO توزيع الحمل الحراري والدوران الاستوائي، وقد يرتبط بتغيرات مناخية بعيدة عبر أنماط اتصال تختلف حسب الموسم والمنطقة. لا تكون الاستجابة الإقليمية ثابتة أو حتمية."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"إل نينيو والتذبذب الجنوبي والاتصالات المناخية","text":"فسر لماذا قد تختلف استجابة منطقتين بعيدتين للطور نفسه من ENSO. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا قد تختلف استجابة منطقتين بعيدتين للطور نفسه من ENSO."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9180,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('indian-ocean-dipole-seasonal','ثنائية القطب في المحيط الهندي','تدرج حرارة السطح والاقتران الجوي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يصف مؤشر ثنائية القطب تباين حرارة سطح البحر بين أجزاء من المحيط الهندي الاستوائي، وقد يرتبط بتغيرات الحمل المطري والدوران الإقليمي. تتداخل آثاره مع ENSO والدورة الموسمية."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ثنائية القطب في المحيط الهندي","text":"اشرح دور التدرج الحراري بين غرب وشرق المحيط الهندي في الاقتران الجوي. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح دور التدرج الحراري بين غرب وشرق المحيط الهندي في الاقتران الجوي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9190,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('madden-julian-oscillation','تذبذب مادن–جوليان','الحمل الحراري المداري المتنقل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل MJO اضطراباً واسع النطاق في الحمل الحراري والدوران ينتقل شرقاً عبر المناطق المدارية، وقد يؤثر في احتمالات الأمطار والأنظمة الجوية خارج المدار. تتغير قوته وموقعه وسرعة انتقاله."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تذبذب مادن–جوليان","text":"حدد كيف يمكن لموقع طور MJO أن يغير التوقعات الاحتمالية الإقليمية. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد كيف يمكن لموقع طور MJO أن يغير التوقعات الاحتمالية الإقليمية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9200,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('north-atlantic-oscillation','التذبذب شمال الأطلسي','فرق الضغط ومسارات المنخفضات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعبر NAO عن تغير نمط الضغط بين شمال الأطلسي شبه المداري والقطبي، ويرتبط بتحولات مسارات العواصف والحرارة والهطول في أجزاء من أوروبا والمناطق المجاورة."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التذبذب شمال الأطلسي","text":"فسر بصورة عامة اختلاف أنماط الطقس الأوروبية بين طورين من NAO. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر بصورة عامة اختلاف أنماط الطقس الأوروبية بين طورين من NAO."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9210,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
