('seasonal-hindcast-design','تصميم إعادة التنبؤ الموسمي','السجل التاريخي المتسق للنموذج','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم hindcasts لتقييم النظام عبر مواسم سابقة باستخدام إعدادات متسقة قدر الإمكان مع النظام التشغيلي. تؤثر مدة السجل وتغير النموذج وتوافر المشاهدات في جودة التقييم."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تصميم إعادة التنبؤ الموسمي","text":"ضع شروطاً لاختيار فترة hindcast مناسبة لنظام موسمي. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع شروطاً لاختيار فترة hindcast مناسبة لنظام موسمي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9240,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('seasonal-forecast-calibration','معايرة التنبؤ الموسمي','تصحيح الانحياز وتحسين الاحتمالات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم المعايرة العلاقة التاريخية بين توقعات النموذج والمشاهدات لتحسين الاحتمالات أو التوزيعات. يجب تنفيذها على بيانات تدريب منفصلة عن فترة التقييم لتجنب تسرب المعلومات."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"معايرة التنبؤ الموسمي","text":"اشرح كيف يمكن فصل بيانات المعايرة عن بيانات التحقق. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن فصل بيانات المعايرة عن بيانات التحقق."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9250,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'مصادر القابلية للتنبؤ والأنماط المناخية'),
('tercile-probability-forecasts','توقعات الفئات الثلاثية','أقل من الطبيعي وقريب من الطبيعي وأعلى منه','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعرض التوقعات الموسمية غالباً احتمالات الفئات الثلاثية نسبة إلى فترة مرجعية ومناخ محلي محدد. يجب بيان الفترة المرجعية وتعريف الحدود وعدم تفسير الفئة الأرجح على أنها يقين."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"توقعات الفئات الثلاثية","text":"فسر توقعاً يعطي الفئة الأعلى احتمالاً 45% والفئتين الأخريين احتمالات مختلفة. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر توقعاً يعطي الفئة الأعلى احتمالاً 45% والفئتين الأخريين احتمالات مختلفة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9260,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-climate-anomaly-maps','خرائط الشذوذ المناخي الموسمي','الفرق عن المعدل المرجعي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمثل خرائط الشذوذ الفرق بين القيمة المتوقعة والمعدل المناخي لفترة مرجعية. تعتمد دلالتها على جودة المرجع وطول سجله وتجانسه، ويجب التمييز بين الشذوذ المطلق والنسبي."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"خرائط الشذوذ المناخي الموسمي","text":"قارن خريطتي شذوذ لدرجات الحرارة والهطول مع مراعاة وحداتهما. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن خريطتي شذوذ لدرجات الحرارة والهطول مع مراعاة وحداتهما."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9270,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('multi-model-seasonal-consensus','التوافق بين النماذج الموسمية','تجميع الأنظمة وتفاوت الأداء','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع المنتجات متعددة النماذج توقعات أنظمة مختلفة للاستفادة من تنوعها وتقليل الاعتماد على نموذج واحد. يتطلب التجميع مراعاة اختلاف المهارة والانحياز والتغطية وتوفر hindcasts."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التوافق بين النماذج الموسمية","text":"اقترح طريقة وزن أو تجميع مع توضيح مخاطر إعطاء وزن متساوٍ دائماً. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح طريقة وزن أو تجميع مع توضيح مخاطر إعطاء وزن متساوٍ دائماً."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9280,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-forecast-downscaling','الخفض المكاني للتنبؤات الموسمية','من الإشارة واسعة النطاق إلى الإقليم','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحول الخفض المكاني المعلومات واسعة النطاق إلى منتجات إقليمية باستخدام علاقات إحصائية أو نماذج ديناميكية. لا يخلق الخفض مهارة غير موجودة في المصدر، ويحتاج إلى تحقق محلي."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الخفض المكاني للتنبؤات الموسمية","text":"قارن الخفض الإحصائي والديناميكي من حيث البيانات والكلفة والقيود. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن الخفض الإحصائي والديناميكي من حيث البيانات والكلفة والقيود."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9290,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-precipitation-probability','التنبؤ الاحتمالي للهطول الموسمي','التوزيع والعتبات ومخاطر الجفاف','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب التنبؤ بالهطول الموسمي عرض احتمالات التوزيع أو الفئات، مع تحليل العجز والفائض والتباين المكاني. لا تعني إشارة موسم رطب أن كل شهر أو موقع سيكون ممطراً."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التنبؤ الاحتمالي للهطول الموسمي","text":"فسر توقعاً موسمياً إيجابياً للهطول مع وجود احتمال معتبر للعجز. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر توقعاً موسمياً إيجابياً للهطول مع وجود احتمال معتبر للعجز."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9300,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-temperature-probability','التنبؤ الاحتمالي لحرارة الموسم','المتوسط والانحراف والحدود القصوى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم منتجات الحرارة الموسمية احتمالات الشذوذ أو الفئات، وقد تخفي المتوسطات فترات متطرفة قصيرة. ينبغي التمييز بين توقع متوسط الموسم وتوقع موجات حر محددة."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التنبؤ الاحتمالي لحرارة الموسم","text":"اشرح لماذا لا يمكن استنتاج توقيت موجة حر من متوسط موسمي أعلى من الطبيعي. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا لا يمكن استنتاج توقيت موجة حر من متوسط موسمي أعلى من الطبيعي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9310,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-drought-outlook','التوقع الموسمي للجفاف','المطر والتبخر والطلب المائي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعتمد تقييم الجفاف على أكثر من الهطول، إذ تتداخل الحرارة والتبخر والنتح ورطوبة التربة والتدفقات. تختلف المؤشرات بحسب نوع الجفاف والقطاع المستخدم."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التوقع الموسمي للجفاف","text":"قارن مؤشر جفاف مطري بمؤشر يدمج الطلب التبخري. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مؤشر جفاف مطري بمؤشر يدمج الطلب التبخري."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9320,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-forecast-verification','التحقق من التنبؤات الموسمية','المهارة والموثوقية والقيمة المضافة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيم التحقق الموسمي مهارة الاحتمالات والشذوذات عبر مواسم متعددة، مع مقارنتها بالمناخ المرجعي والتوقعات المرجعية البسيطة. يجب فصل المهارة بحسب المنطقة والموسم والمتغير."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التحقق من التنبؤات الموسمية","text":"اقترح مؤشرات تحقق لتوقع احتمالات الفئات الثلاثية. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح مؤشرات تحقق لتوقع احتمالات الفئات الثلاثية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9330,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-outlook-communication','صياغة ونشر النظرة المناخية الموسمية','اللغة الاحتمالية وحدود التفسير','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يجب أن تعرض النظرة الموسمية الاحتمالات والفترة والمجال المكاني والمعدل المرجعي ومستوى الثقة والقيود. تساعد الخرائط والنصوص التفسيرية على منع تحويل الاحتمال إلى وعد حتمي."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"صياغة ونشر النظرة المناخية الموسمية","text":"أعد صياغة نتيجة موسمية احتمالية في رسالة واضحة لصانع قرار. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أعد صياغة نتيجة موسمية احتمالية في رسالة واضحة لصانع قرار."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9340,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات'),
('seasonal-climate-services','الخدمات المناخية المبنية على التنبؤ الموسمي','الزراعة والمياه والطاقة والصحة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تربط الخدمات المناخية التوقعات الموسمية باحتياجات القطاعات عبر مؤشرات ملائمة وتوقيت مناسب وحوار مع المستخدمين. تتطلب تحويل التوقع إلى أثر محتمل دون تجاوز حدود المهارة."},{"type":"heading","text":"الأساس المناخي والإحصائي"},{"type":"text","text":"تستند التوقعات الموسمية إلى قابلية التنبؤ المرتبطة بالمكونات البطيئة نسبياً والأنماط واسعة النطاق، ثم تحول مخرجات المجموعات إلى توزيعات احتمالية أو شذوذات. يجب التمييز بين التنبؤ الجوي اليومي والتوقع المناخي الموسمي، وبين الاحتمال والنتيجة المحققة."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["سجلات مناخية مرجعية متجانسة وطويلة نسبياً.","مخرجات مجموعات تنبؤ موسمية مع أرشيف hindcast.","مؤشرات محيطية وجوية واسعة النطاق ذات صلة.","بيانات رصد إقليمية للتحقق والمعايرة.","تعريف واضح للفترة المرجعية والفئات والمنتج المستهدف."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الموسم والمتغير والمنطقة واحتياج المستخدم.","افحص مصادر القابلية للتنبؤ وسياق الأنماط المناخية.","حلل المجموعات والاحتمالات والانحياز التاريخي.","عاير المنتج واختبره على فترة مستقلة.","تحقق من المهارة ثم صغ الرسالة مع حدود الثقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الخدمات المناخية المبنية على التنبؤ الموسمي","text":"صمم منتجاً موسمياً موجهاً لإدارة الموارد المائية مع توضيح حدوده. استخدم سيناريو افتراضياً، وبيّن كيف تتغير دلالة المنتج عند اختلاف الاحتمالات والمرجع المناخي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم منتجاً موسمياً موجهاً لإدارة الموارد المائية مع توضيح حدوده."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["تحويل الاحتمال إلى تنبؤ حتمي.","استخدام فترة مرجعية غير موثقة أو غير متجانسة.","تجاهل اختلاف المهارة بين المناطق والمواسم.","الخلط بين متوسط الموسم وتوقيت الأحداث اليومية.","تقييم المعايرة على البيانات نفسها المستخدمة في بنائها."]},{"type":"callout","text":"التوقع الموسمي يصف تغير الاحتمالات على مدى أشهر، ولا يحل محل التنبؤات اليومية أو التحذيرات قصيرة المدى."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تتطلب الخدمة المناخية الموسمية دمج النماذج والمشاهدات والأنماط واسعة النطاق والتحقق الاحتمالي. وتتحقق فائدتها عندما تترجم الاحتمالات إلى معلومات قطاعية واضحة مع توثيق القيود."}]}'::jsonb,9350,55,'["شرح مصدر القابلية للتنبؤ الموسمي أو منهج إنتاجه","تحليل المخرجات الاحتمالية والبيانات المرجعية","تقييم المهارة وصياغة منتج مناخي قابل للاستخدام"]'::jsonb,'إنتاج التوقع الموسمي والتحقق والخدمات')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='مصادر القابلية للتنبؤ والأنماط المناخية' then u1.id else u2.id end,'التنبؤات الموسمية والخدمات المناخية الاحتمالية',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;